#include "stabilization.hpp"
#include <iostream>
#include <map>
#include <fstream>
#include <cstdio>
using namespace m1pn;
static void check(bool b,const std::string&s){if(!b)throw std::runtime_error(s);}
static double rel(double a,double b){return std::abs(a-b)/std::max({1.,std::abs(a),std::abs(b)});}
static Field affine(const Spatial&f){Field u(f.nodes,1);for(int i=0;i<f.nodes;++i)u(i,0)=.7+f.coordinates(i,0)-.3*f.coordinates(i,1)+.2*f.coordinates(i,2);return u;}
static Field dense_reference(const Spatial&f,const Field&u){struct I{int node;double w,nu;Eigen::MatrixXd A;std::vector<int>d;};std::vector<I>in;std::vector<std::vector<int>>star(f.nodes);for(int e=0;e<f.mesh->GetNE();++e){auto*el=f.space->GetFE(e);auto*tr=f.mesh->GetElementTransformation(e);mfem::Array<int>d;f.space->GetElementDofs(e,d);int nd=d.Size();const auto&rule=mfem::IntRules.Get(el->GetGeomType(),6);for(int a=0;a<nd;++a){double w=0;for(int p=0;p<rule.GetNPoints();++p){const auto&ip=rule.IntPoint(p);tr->SetIntPoint(&ip);mfem::Vector s(nd);el->CalcShape(ip,s);w+=ip.weight*tr->Weight()*s[a];}const auto&ip=el->GetNodes().IntPoint(a);tr->SetIntPoint(&ip);mfem::DenseMatrix g(nd,f.dimension);el->CalcPhysDShape(*tr,g);Eigen::MatrixXd A=Eigen::MatrixXd::Zero(3,nd);for(int j=0;j<nd;++j)for(int r=0;r<f.dimension;++r)A(r,j)=g(j,r);int id=in.size();star[d[a]].push_back(id);in.push_back({d[a],w,.5*f.diameter[d[a]],A,std::vector<int>(d.begin(),d.end())});}}
 Eigen::MatrixXd D=Eigen::MatrixXd::Zero(3*in.size(),f.nodes);Eigen::VectorXd W=Eigen::VectorXd::Zero(3*in.size());for(int node=0;node<f.nodes;++node){double m=0;for(int r:star[node])m+=in[r].w;for(int r:star[node])for(int k=0;k<3;++k){int row=3*r+k;W[row]=in[r].w*in[r].nu;for(int j=0;j<(int)in[r].d.size();++j)D(row,in[r].d[j])+=in[r].A(k,j);for(int s:star[node])for(int j=0;j<(int)in[s].d.size();++j)D(row,in[s].d[j])-=in[s].w/m*in[s].A(k,j);}}return -D.transpose()*W.asDiagonal()*D*u;}
static void algebra(const MeshSpec&s){Spatial f(s);SpatialStabilization k(f,"gradient-defect",.5,1.);Field u=Field::Random(f.nodes,2),p,z=k.apply(u,&p);check((u.array()*z.array()).sum()<=1e-9,"Gram work must be nonpositive");check(z.colwise().sum().norm()<2e-9,"componentwise conservation");check((z-dense_reference(f,u)).norm()<2e-8,"independently assembled dense incidence Gram");if(!s.periodic){Field a=affine(f);check(k.apply(a).norm()<2e-8,"open affine exactness");}Field g=Field::Zero(f.nodes,2);for(int e=0;e<(int)f.pairs.size();++e){g.row(f.pairs[e].i)+=p.row(e);g.row(f.pairs[e].j)-=p.row(e);}check((g-z).norm()<2e-8,"pair ledger reconstructs Z");
 // Independent bilinear-form symmetry check.
 Field v=Field::Random(f.nodes,1),x=k.apply(v),y=k.apply(affine(f));check(std::abs((affine(f).array()*x.array()).sum()-(v.array()*y.array()).sum())<2e-8,"Gram operator symmetry");
 SpatialStabilization o(f,"biharmonic-original",.01,1.),c(f,"biharmonic-corrected",.01,1.);check((u.array()*o.apply(u).array()).sum()<=1e-8,"original biharmonic PSD");check((u.array()*c.apply(u).array()).sum()<=1e-8,"corrected biharmonic PSD");if(!s.periodic)check(c.apply(affine(f)).norm()<3e-8,"corrected stiffness affine exactness");}
int main(){try{
 const double gamma=.5; const int n1=16; MeshSpec one{1,n1,true,false,false,""};Spatial f1(one);SpatialStabilization k1(f1,"gradient-defect",gamma,1.);Field u(n1,1);for(int i=0;i<n1;++i)u(i,0)=std::sin(2*pi*i/n1);Field z=k1.apply(u);double h=1./n1;double work=-(u.array()*z.array()).sum();Field Lu=Field::Zero(n1,1);for(int i=0;i<n1;++i)Lu(i,0)=2*u(i,0)-u((i+n1-1)%n1,0)-u((i+1)%n1,0);check(rel(work,gamma/4*Lu.squaredNorm())<2e-9,"periodic 1D exact nu/(4h) L_G^2 identity");
 // Exact Cartesian periodic Q1 residual symbol: A=nu*h/4 sum_r L_r^2.
 const int n=5;MeshSpec cube{3,n,true,false,false,""};Spatial f3(cube);SpatialStabilization k3(f3,"gradient-defect",gamma,1.);double h3=1./n,nu=gamma*std::sqrt(3.)*h3;for(auto mode:std::vector<std::array<int,3>>{{1,0,0},{1,2,1},{2,2,2}}){Field v(f3.nodes,1);for(int i=0;i<f3.nodes;++i){v(i,0)=std::cos(2*pi*(mode[0]*f3.coordinates(i,0)+mode[1]*f3.coordinates(i,1)+mode[2]*f3.coordinates(i,2)) );}Field av=-k3.apply(v);double lam=0;for(int r=0;r<3;++r)lam+=4*nu*h3*std::pow(std::sin(pi*mode[r]/n),4);for(int i=0;i<f3.nodes;++i)check(std::abs(av(i,0)-lam*v(i,0))<2e-8,"3D Q1 Fourier eigen-residual");}
 // Open 1D quadratic boundary countercheck from paper (4.24).
 MeshSpec open{1,8,false,false,false,""};Spatial fo(open);SpatialStabilization ko(fo,"gradient-defect",gamma,1.);Field q(fo.nodes,1);for(int i=0;i<fo.nodes;++i){double x=fo.coordinates(i,0);q(i,0)=x*x;}Field zq=ko.apply(q);check(rel(zq(0,0)/fo.mass[0],-gamma/8)<2e-9,"open quadratic endpoint rate -gamma*h");
 algebra({1,12,true,false,false,""});algebra({3,3,true,false,false,""});algebra({3,2,false,true,false,""});algebra({3,2,false,false,false,""});
 // A genuinely mapped Q1 mesh checks physical-gradient affine reproduction.
 const char *path="tmp/m1pn_r2_warped_q1.mesh";{mfem::Mesh m=mfem::Mesh::MakeCartesian2D(3,3,mfem::Element::QUADRILATERAL,true);for(int i=0;i<m.GetNV();++i){double*v=m.GetVertex(i);double x=v[0],y=v[1];v[0]=x+.12*y*(1-y);v[1]=y+.08*x*(1-x);}std::ofstream out(path);m.Print(out);}MeshSpec warped{2,3,false,false,false,path};Spatial fw(warped);SpatialStabilization kw(fw,"gradient-defect",gamma,1.);check(kw.apply(affine(fw)).norm()<3e-8,"warped Q1 affine exactness");std::remove(path);
 std::cout<<"R2 stabilization identities passed\n";return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
